steps.script:
set -euo pipefail
[ "${log_path}" != '<log_path>' ] || { echo '缺少参数 log_path（远端绝对路径）' >&2; exit 2; }
[ -f "${log_path}" ] || { echo "日志不存在 ${log_path}" >&2; exit 3; }
[ -r "${log_path}" ] || { echo "日志不可读 ${log_path}" >&2; exit 4; }
echo "log-ready ${log_path} $(wc -c < "${log_path}") 字节"
